class XgenError(Exception):
    """
    Base exception class for all xgen-client related errors.
    """
    pass


class XgenClientNotFound(XgenError):
    """
    Exception raised when the xgen-client is not found in the specified directory.
    """
    pass


class MissingSshParameters(XgenError):
    """
    Exception raised when SSH parameters are missing for remote VM connection.
    """
    pass


class StopXgenClientError(XgenError):
    """
    Exception raised when the xgen-client process cannot be stopped.
    """
    pass


class XgenClientStartError(XgenError):
    """
    Exception raised when the xgen-client fails to start on the remote VM.
    """
    pass


class InvalidConfigError(XgenError):
    """
    Exception raised when the provided configuration for xGen is invalid.
    """
    pass
